import {writeFileSync} from 'node:fs';
const a=process.env.CLOUDFLARE_ACCOUNT_ID,t=process.env.CLOUDFLARE_API_TOKEN;
if(!a||!t)throw Error('Cloudflare credentials unavailable');
const db='0d12a7cc-12a9-4c71-b55b-61dfd2dac4d4';
const report={at:new Date().toISOString(),mode:'READ_ONLY',productionWrites:0,providerCalls:0,database:db,queries:{},errors:[]};
async function query(sql){if(!/^\s*(SELECT|WITH)\b/i.test(sql)||/\b(INSERT|UPDATE|DELETE|ALTER|DROP|CREATE|REPLACE)\b/i.test(sql))throw Error('Non-read SQL rejected');const r=await fetch('https://api.cloudflare.com/client/v4/accounts/'+encodeURIComponent(a)+'/d1/database/'+db+'/query',{method:'POST',headers:{Authorization:'Bearer '+t,'Content-Type':'application/json'},body:JSON.stringify({sql}),signal:AbortSignal.timeout(45000)});const j=await r.json();if(!r.ok||!j.success||!j.result?.[0]?.success)throw Error('D1 read failed HTTP '+r.status+' codes '+(j.errors||[]).map(x=>x.code).join(','));const x=j.result[0];if(Number(x.meta?.rows_written||0)!==0)throw Error('Unexpected write');return {rows:x.results,rows_read:x.meta?.rows_read,rows_written:x.meta?.rows_written}}
const queries={
 entries_by_engine:`SELECT engine,COUNT(*) n,COUNT(DISTINCT fixture_id) fixtures,MIN(captured_at) first_at,MAX(captured_at) last_at,SUM(resolution='RESOLVED') resolved,SUM(resolution='RESOLVED' AND unit_pl IS NOT NULL) pl_known,SUM(line IS NOT NULL AND price>1) line_price_known,SUM(resolution='RESOLVED' AND price>1 AND line IS NOT NULL AND unit_pl IS NOT NULL) priced_resolved,ROUND(SUM(CASE WHEN resolution='RESOLVED' THEN unit_pl END),5) stored_unit_pl,ROUND(AVG(CASE WHEN resolution='RESOLVED' THEN unit_pl END)*100,3) stored_paper_roi_pct FROM entry_decisions GROUP BY engine`,
 entries_states:`SELECT engine,policy_status,resolution,outcome,COUNT(*) n,COUNT(DISTINCT fixture_id) fixtures,ROUND(SUM(unit_pl),4) unit_pl FROM entry_decisions GROUP BY engine,policy_status,resolution,outcome ORDER BY engine,n DESC`,
 entries_market:`SELECT engine,market_type,selection,odds_format,COUNT(*) n,COUNT(DISTINCT fixture_id) fixtures,SUM(resolution='RESOLVED') resolved,ROUND(AVG(price),4) avg_price,ROUND(SUM(CASE WHEN resolution='RESOLVED' THEN unit_pl END),4) unit_pl FROM entry_decisions GROUP BY engine,market_type,selection,odds_format ORDER BY n DESC`,
 entries_unique_first:`WITH r AS (SELECT *,ROW_NUMBER() OVER(PARTITION BY fixture_id,engine ORDER BY captured_at,id) rn FROM entry_decisions) SELECT engine,policy_status,COUNT(*) n,SUM(resolution='RESOLVED') resolved,SUM(resolution='RESOLVED' AND unit_pl IS NOT NULL AND price>1 AND line IS NOT NULL) eligible_pl,ROUND(SUM(CASE WHEN resolution='RESOLVED' AND unit_pl IS NOT NULL AND price>1 AND line IS NOT NULL THEN unit_pl END),4) unit_pl FROM r WHERE rn=1 GROUP BY engine,policy_status`,
 entries_daily:`SELECT date(captured_at/1000,'unixepoch') day_utc,engine,COUNT(*) n,COUNT(DISTINCT fixture_id) fixtures,SUM(resolution='RESOLVED') resolved,ROUND(SUM(CASE WHEN resolution='RESOLVED' THEN unit_pl END),4) unit_pl FROM entry_decisions GROUP BY day_utc,engine ORDER BY day_utc DESC LIMIT 60`,
 qsig_states:`SELECT engine,outcome,COUNT(*) n,COUNT(DISTINCT fixture_id) fixtures,MIN(signal_at) first_at,MAX(signal_at) last_at FROM qsig_results GROUP BY engine,outcome ORDER BY engine,n DESC`,
 validation_states:`SELECT validation_type,result_key,COUNT(*) n,COUNT(DISTINCT fixture_id) fixtures,MIN(created_at) first_at,MAX(created_at) last_at FROM validation_results GROUP BY validation_type,result_key ORDER BY validation_type,n DESC`,
 validation_bets:`SELECT json_extract(payload_json,'$.engine') engine,json_extract(payload_json,'$.sample_type') sample_type,result_key,COUNT(*) n,COUNT(DISTINCT fixture_id) fixtures,SUM(json_extract(payload_json,'$.profit_unit') IS NOT NULL) profit_unit_known,ROUND(SUM(json_extract(payload_json,'$.profit_unit')),4) profit_unit,ROUND(SUM(json_extract(payload_json,'$.profit')),4) profit,ROUND(SUM(json_extract(payload_json,'$.stake')),4) stakes FROM validation_results WHERE validation_type NOT LIKE 'PUSH_%' GROUP BY engine,sample_type,result_key ORDER BY n DESC LIMIT 80`,
 push_buckets:`SELECT validation_type,CASE WHEN json_extract(payload_json,'$.signal_value') IS NULL THEN 'MISSING' WHEN json_extract(payload_json,'$.signal_value')<60 THEN '<60' WHEN json_extract(payload_json,'$.signal_value')<70 THEN '60-69' WHEN json_extract(payload_json,'$.signal_value')<80 THEN '70-79' ELSE '80+' END score_bucket,result_key,COUNT(*) n,COUNT(DISTINCT fixture_id) fixtures FROM validation_results WHERE validation_type LIKE 'PUSH_%' GROUP BY validation_type,score_bucket,result_key ORDER BY validation_type,score_bucket,result_key`,
 push_daily:`SELECT date(created_at/1000,'unixepoch') day_utc,validation_type,result_key,COUNT(*) n,COUNT(DISTINCT fixture_id) fixtures FROM validation_results WHERE validation_type LIKE 'PUSH_%' GROUP BY day_utc,validation_type,result_key ORDER BY day_utc DESC LIMIT 100`,
 outcome_integrity:`SELECT e.engine,COUNT(*) joined,SUM(e.outcome IS NOT o.outcome) outcome_mismatch,SUM(e.unit_pl IS NOT o.unit_pl) pl_mismatch FROM entry_decisions e JOIN entry_outcomes o ON o.decision_id=e.id GROUP BY e.engine`,
 validation_payload_keys:`SELECT v.validation_type,j.key,j.type,COUNT(*) n FROM validation_results v,json_each(v.payload_json) j WHERE j.key IN ('sample_type','source','engine','resolution','target','settlement_basis','profit_unit','signal_value','score','score_home','score_away','gap_signed','minute','outcome','hit','evidence_status','unknown_reason') GROUP BY v.validation_type,j.key,j.type ORDER BY v.validation_type,j.key`
};
for(const [name,sql] of Object.entries(queries)){try{report.queries[name]=await query(sql)}catch(e){report.errors.push({query:name,error:e.message})}}
writeFileSync('football-edge-performance-readonly.json',JSON.stringify(report,null,2));console.log('FE_PERFORMANCE_READONLY '+JSON.stringify(report));if(report.errors.length)process.exitCode=1;
